window.ScripturaLexicons.BDAG_PART_0165 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thanatodes-bdag\" data-source=\"BDAG\" data-search=\"θανατώδης, ες adjetivo de dois gêneros mortal; fatal; mortífero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θανατώδης, ες</td><td>adjetivo de dois gêneros</td><td>mortal; fatal; mortífero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thapto-bdag\" data-source=\"BDAG\" data-search=\"θάπτω verbo sepultar; enterrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάπτω</td><td>verbo</td><td>sepultar; enterrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thara-bdag\" data-source=\"BDAG\" data-search=\"Θάρα, ὁ nome próprio masculino indeclinável Terá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θάρα, ὁ</td><td>nome próprio masculino indeclinável</td><td>Terá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-tharreo-bdag\" data-source=\"BDAG\" data-search=\"θαρρέω verbo ter confiança; ser corajoso; confiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαρρέω</td><td>verbo</td><td>ter confiança; ser corajoso; confiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-tharseo-bdag\" data-source=\"BDAG\" data-search=\"θαρσέω verbo ser corajoso; ter ânimo; não temer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαρσέω</td><td>verbo</td><td>ser corajoso; ter ânimo; não temer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-tharsos-bdag\" data-source=\"BDAG\" data-search=\"θάρσος, ους, τό substantivo neutro coragem; ânimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θάρσος, ους, τό</td><td>substantivo neutro</td><td>coragem; ânimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thatton-bdag\" data-source=\"BDAG\" data-search=\"θᾶττον advérbio remissivo mais rapidamente; ver ταχέως 1b BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θᾶττον</td><td>advérbio remissivo</td><td>mais rapidamente; ver ταχέως 1b</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thauma-bdag\" data-source=\"BDAG\" data-search=\"θαῦμα, ατος, τό substantivo neutro maravilha; prodígio; admiração; espanto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαῦμα, ατος, τό</td><td>substantivo neutro</td><td>maravilha; prodígio; admiração; espanto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thaumazo-bdag\" data-source=\"BDAG\" data-search=\"θαυμάζω verbo admirar-se; maravilhar-se; espantar-se; admirar; respeitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαυμάζω</td><td>verbo</td><td>admirar-se; maravilhar-se; espantar-se; admirar; respeitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thaumasios-bdag\" data-source=\"BDAG\" data-search=\"θαυμάσιος, α, ον adjetivo maravilhoso; notável; admirável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαυμάσιος, α, ον</td><td>adjetivo</td><td>maravilhoso; notável; admirável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thaumastos-bdag\" data-source=\"BDAG\" data-search=\"θαυμαστός, ή, όν adjetivo maravilhoso; admirável; extraordinário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαυμαστός, ή, όν</td><td>adjetivo</td><td>maravilhoso; admirável; extraordinário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thaumastos-adv-bdag\" data-source=\"BDAG\" data-search=\"θαυμαστῶς advérbio maravilhosamente; extraordinariamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θαυμαστῶς</td><td>advérbio</td><td>maravilhosamente; extraordinariamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thea-bdag\" data-source=\"BDAG\" data-search=\"θεά, ᾶς, ἡ substantivo feminino deusa; divindade feminina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεά, ᾶς, ἡ</td><td>substantivo feminino</td><td>deusa; divindade feminina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theama-bdag\" data-source=\"BDAG\" data-search=\"θέαμα, ατος, τό substantivo neutro espetáculo; visão; cena notável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέαμα, ατος, τό</td><td>substantivo neutro</td><td>espetáculo; visão; cena notável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theaomai-bdag\" data-source=\"BDAG\" data-search=\"θεάομαι verbo depoente ver; contemplar; observar; visitar; perceber BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεάομαι</td><td>verbo depoente</td><td>ver; contemplar; observar; visitar; perceber</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theatrizo-bdag\" data-source=\"BDAG\" data-search=\"θεατρίζω verbo expor publicamente; envergonhar diante de todos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεατρίζω</td><td>verbo</td><td>expor publicamente; envergonhar diante de todos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theatron-bdag\" data-source=\"BDAG\" data-search=\"θέατρον, ου, τό substantivo neutro teatro; lugar de assembleia; espetáculo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέατρον, ου, τό</td><td>substantivo neutro</td><td>teatro; lugar de assembleia; espetáculo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thegri-bdag\" data-source=\"BDAG\" data-search=\"Θεγρί, ὁ nome próprio masculino indeclinável Tegrí BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θεγρί, ὁ</td><td>nome próprio masculino indeclinável</td><td>Tegrí</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theion-sulfur-bdag\" data-source=\"BDAG\" data-search=\"θεῖον, ου, τό substantivo neutro enxofre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεῖον, ου, τό</td><td>substantivo neutro</td><td>enxofre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theios-bdag\" data-source=\"BDAG\" data-search=\"θεῖος, θεία, θεῖον adjetivo e substantivo neutro divino; divindade; sobrenatural BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεῖος, θεία, θεῖον</td><td>adjetivo e substantivo neutro</td><td>divino; divindade; sobrenatural</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-thanatodes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">θάνατος</span> e -<span class=\"greek\">ώδης</span>; Hipócrates e autores posteriores.) <strong>Mortal, fatal, mortífero</strong> (Eliano, NA 7, 5; Polieno 4, 3, 28; SEG VIII 549, 7 [século I a.C.]; Fílon, Abr. 46), acerca dos desejos, Hm 12, 2, 3.</p></section></article>\n<article id=\"entry-thapto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἔθαπτον</span>; futuro <span class=\"greek\">θάψω</span>, LXX; primeiro aoristo <span class=\"greek\">ἔθαψα</span>. Passiva: segundo futuro <span class=\"greek\">ταφήσομαι</span>, LXX; segundo aoristo <span class=\"greek\">ἐτάφην</span>; perfeito na terceira pessoa singular <span class=\"greek\">τέθαπται</span>, 3Km 18:31 (Homero e outros; inscrições, papiros, LXX, pseudepígrafos, Josefo, Ar. [Milne 74, 22s.], Justino, Melitão, Atanásio). <strong>Sepultar, enterrar</strong>, com acusativo <span class=\"greek\">τινά</span>, «alguém» (Josefo, Bell. 4, 317; Ant. 4, 78), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:21s</a>.; 14:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:59s</a>. (ver <span class=\"greek\">νεκρός</span> B2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:9</a>; GPt 2:5. Com acusativo de coisa <span class=\"greek\">τὶ</span>: <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>, «o corpo», GPt 6:23. Com objeto acusativo subentendido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:6</a>, 10 (cf. Políbio 12, 26, 7, <span class=\"greek\">τοὺς</span> <span class=\"greek\">πρεσβυτέρους</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νέων</span> <span class=\"greek\">θάπτεσθαι</span>). Na passiva (Josefo, Ant. 4, 202; Justino, D. 78, 8; 118, 1; Melitão, P. 8, 56 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:4</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> … <span class=\"greek\">ἔνθα</span> <span class=\"greek\">ἐτάφη</span>, «o lugar onde foi sepultado», Pápias 3:3 (sobre a leitura, ver E. Preuschen, <em>Antilegomena</em>, 1905, 98, 20, aparato). — P. Heinisch, <em>Die Trauergebräuche bei den Israeliten</em> (<em>Biblische Zeitfragen</em> 13), 1931, 70–100; D. Kurtz e J. Boardman, <em>Greek Burial Customs</em>, 1971; B. 291s.; DELG; M-M.</p></section></article>\n<article id=\"entry-thara-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θάρα, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Também <span class=\"greek\">Θαρά</span>; indeclinável; hebraico תֶּרַח; LXX, Fílon [<span class=\"greek\">Θάρρα</span>]; em Josefo, <span class=\"greek\">Θέρρος</span>, variante <span class=\"greek\">Θάρρος</span>, genitivo <span class=\"greek\">ου</span> [Ant. 1, 252].) <strong>Terá</strong>, pai de Abraão (Gn 11:24ss.; Js 24:2; 1Cr 1:26), na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:34</a>. — BHHW III 1964s.</p></section></article>\n<article id=\"entry-tharreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperativo de primeiro aoristo, segunda pessoa plural, <span class=\"greek\">θαρρήσατε</span> (Br 4:27, códice B); infinitivo <span class=\"greek\">θαρρῆσαι</span>. Forma ática (Platão), que aumenta em frequência junto a <span class=\"greek\">θαρσέω</span> (ver verbete) na coiné (Schwyzer I 285), também em inscrições, papiros, LXX (Thackeray 123), Fílon, Josefo, Ant. 6, 181; 20, 175; Vi. 143; Justino, D. 89, 3; Atanásio 2, 2. — Thumb 77. Sobre as associações desse termo com os mistérios eleusinos, ver R. Joly, RevÉtGr 68, 1955, 164–70. <strong>Ter certeza a respeito de alguma coisa, ter confiança, ser corajoso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:6</a>, 8. <span class=\"greek\">ὥστε</span> <span class=\"greek\">θαρροῦντας</span> (IMaronIsis 11s.) <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">λέγειν</span>, «para que possamos falar com confiança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:6</a>. <span class=\"greek\">θ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «poder confiar em alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:16</a>; <strong>mostrar ousadia para com alguém</strong>, <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:1</a>; cf. versículo 2 (ver <span class=\"greek\">δέομαι</span> a<span class=\"greek\">β</span>). <span class=\"greek\">εἰ</span> <span class=\"greek\">ἄρα</span> … <span class=\"greek\">θαρρεῖς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Πέτρου</span> <span class=\"greek\">θεῷ</span>, «se, então, realmente crês no Deus de Pedro», AcPt Ox 849, 7 (latim <em>credis</em>, códice Vercellensis). — DELG, s.v. <span class=\"greek\">θάρσος</span> A; M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-tharseo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros, LXX; En, JosAs; Josefo, Ant. 1, 187; 8, 293; 11, 334.) No NT — e predominantemente também na LXX — apenas os imperativos <span class=\"greek\">θάρσει</span> e <span class=\"greek\">θαρσεῖτε</span>. Primeiro aoristo <span class=\"greek\">ἐθάρσησα</span>. <strong>Ser firme ou resoluto diante de perigo ou adversidades, cobrar ânimo, ter coragem</strong>, ApcPt 2:5; Hv 4, 1, 8. <span class=\"greek\">θάρσει</span>, «tem coragem! Não tenhas medo!» (Ilíada 4, 184 e outros; Gn 35:17; Sf 3:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:2</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:43</a>, códice D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:11</a> (sobre associações homéricas, Warnecke 57, 12). Plural (Êx 14:13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:33</a>. — M. Parca, ASP 31, 1991, 55s. (referências); B. 1149; DELG, s.v. <span class=\"greek\">θάρσος</span> A; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-tharsos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρσος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; Epicteto 1, 24, 8; 2, 13, 3; SIG 709, 25; PCairMasp 158, 16; LXX, Fílon, Josefo; SibOr 1, 241.) <strong>Coragem, ânimo</strong>: <span class=\"greek\">θ</span>. <span class=\"greek\">λαμβάνειν</span>, «tomar coragem» (Josefo, Ant. 9, 55), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:15</a> (sobre associação com divindade, cf. Plutarco, Mor. 34a); Hv 3, 1, 5. Com <span class=\"greek\">χαρά</span>, «alegria», MPol 12:1. — Schmidt, Syn. III 543–50; cf. <span class=\"greek\">ἀνδρεῖος</span>; TW; Spicq.</p></section></article>\n<article id=\"entry-thatton-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θᾶττον</h1><div class=\"entry-meta\"><span>advérbio remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ταχέως</span> 1b.</p></section></article>\n<article id=\"entry-thauma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαῦμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, LXX; TestSol 3:8, códice D; TestAbr A 3, p. 80, 12 [Stone, p. 8]; 7, p. 84, 26s. [Stone, p. 16s.]; JosAs 28:1; Josefo, Ant. 15, 395.)</p><p class=\"entry-text\">① <strong>Objeto de admiração: maravilha, prodígio</strong> (Herm. Wr. 1, 16; PMich 149 III, 19 [século II d.C.]; Fílon, Plant. 3).</p><p class=\"entry-text\">ⓐ Em geral, <strong>maravilha, coisa extraordinária</strong> (Baquílides 17, 123, de milagre divino; Apiano, Bell. Civ. 1, 16, §67; Filóstrato, Imag. 2, 12, p. 358, 1; 2, 18, p. 371, 6; Himério, Or. 6 [= Or. 2], 25, sobre Xerxes atravessando o estreito; SibOr 3, 281), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:14</a>.</p><p class=\"entry-text\">ⓑ Em sentido especial, <strong>portento, milagre</strong> (Filóstrato, Vi. Apoll. 1, 39, p. 41, 5; SEG VIII 551, 35 [século I a.C.]), <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">θ</span>., «ver uma maravilha ou milagre», MPol 15:1 (cf. Henioch. Com. 3, <span class=\"greek\">ὁρῶ</span> <span class=\"greek\">θαῦμ</span>’ <span class=\"greek\">ἄπιστον</span>; Luciano, Adv. Ind. 8, <span class=\"greek\">θ</span>. <span class=\"greek\">μέγα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὁρῶσιν</span>); TestSol 3:8, códice D.</p><p class=\"entry-text\">② <strong>Estado de espanto diante de algo extraordinariamente impressionante: admiração, assombro</strong> (Homero e outros; Plutarco, Timol. 241 [12, 9], <span class=\"greek\">μετὰ</span> <span class=\"greek\">θαύματος</span>; Jó 18:20): <span class=\"greek\">ἐθαύμασα</span> <span class=\"greek\">ἰδὼν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">θαῦμα</span> <span class=\"greek\">μέγα</span>, «quando a vi, admirei-me com grande espanto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:6</a>; <span class=\"greek\">θ</span>. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">μέγα</span>, «houve grande admiração», AcPl Ha 4, 25. — B. 1093s.; DELG; M-M; Schmidt, Syn. IV 179–88; TW; Sv.</p></section></article>\n<article id=\"entry-thaumazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente e os três seguintes; Homero e outros.) Imperfeito <span class=\"greek\">ἐθαύμαζον</span>; futuro <span class=\"greek\">θαυμάσομαι</span> (<span class=\"greek\">θαυμάσω</span> na LXX; PsSol 2:18); primeiro aoristo <span class=\"greek\">ἐθαύμασα</span>; perfeito, segunda pessoa singular, <span class=\"greek\">τεθαύμακας</span>, Jó 41:1. Passiva: primeiro futuro <span class=\"greek\">θαυμασθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐθαυμάσθην</span>.</p><p class=\"entry-text\">① <strong>Ficar extraordinariamente impressionado ou perturbado por alguma coisa</strong>, na voz ativa.</p><p class=\"entry-text\">ⓐ Intransitivo, <strong>admirar-se, maravilhar-se, ficar espantado</strong> (o contexto determina se em sentido favorável ou desfavorável).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Uso absoluto (Xenofonte, Cyr. 7, 1, 6; Herm. Wr. 14, 4; Josefo, Ant. 6, 56; Justino, D. 89, 3; Taciano 22, 1; Atanásio 11, 1; 24, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a>; 15:31; 22:22; 27:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:20</a>; 15:5 (sobre o silêncio que suscita admiração, cf. Plutarco, Marc. 224 [23]; T. Dwyer, <em>The Motif of Wonder in the Gospel of Mark</em> [JSNT Suppl. 128], 1996); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:63</a>; 8:25; 11:14; 24:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:20</a>; 7:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:13</a>; 13:12, variante de leitura, 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:7</a> (New Docs 5, 35); GJs 8:1; AcPl Ha 10, 29; 11, 2. Às vezes a expressão de espanto é acrescentada mediante <span class=\"greek\">λέγων</span> ou <span class=\"greek\">λέγοντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:27</a>; 9:33; 21:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:7</a>. <span class=\"greek\">θ</span>. <span class=\"greek\">θαῦμα</span> <span class=\"greek\">μέγα</span>, «admirar-se grandemente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:6</a>; ver <span class=\"greek\">θαῦμα</span> 2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com locuções prepositivas: <span class=\"greek\">διά</span> <span class=\"greek\">τι</span>, «admirar-se de alguma coisa» (Isócrates 4, 59; Estrabão 17, 1, 5; Eliano, VH 12, 6; 14, 36), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:6</a>; com o mesmo sentido <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (En 25:1): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χρονίζειν</span> <span class=\"greek\">αὐτόν</span>, «por sua demora», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:21</a> (cf. Eclo 11:21, <span class=\"greek\">μὴ</span> <span class=\"greek\">θαύμαζε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἁμαρτωλοῦ</span>; Is 61:6; En 25:1). A expressão pode também significar «durante sua demora» (B-D-F §404, 3; Rob. 1073). Por outro lado, <span class=\"greek\">θ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, «admirar-se consigo mesmo», Hs 8, 1, 4; 9, 2, 5. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, «diante de algo» (Xenofonte, Mem. 1, 4, 2; 4, 2, 3; Diodoro Sículo 2, 33, 1; Díon Crisóstomo 7 [8], 27; 62 [79], 1, 6; Jó 41:1; 42:11; Jt 11:20), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:33</a>; 4:22 (J. Nolland, JBL 98, 1979, 219–29); 9:43; 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:12</a>; Hs 9, 2, 2. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «acerca de algo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:18</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com oração introduzida por <span class=\"greek\">ὅτι</span>, «admirar-se ou surpreender-se de que» (frequentemente com <span class=\"greek\">πῶς</span> em papiros, cf. POxy 2728, 5s.; 2729, 4 e outros; Pseudo-Xenofonte, Cyn. 1, 3; Fílon, Somn. 2, 183, <span class=\"greek\">μὴ</span> <span class=\"greek\">θαυμάσῃς</span> <span class=\"greek\">ὅτι</span>; Josefo, Vi. 339; Justino, D. 3, 2; POxy 1348 [século III d.C.]; 2783, 6 [século III d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:7</a>; 4:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:6</a> (cf. Demóstenes 18, 159); GJs 16:2; AcPl BMM verso 37. Também com <span class=\"greek\">εἰ</span> (ver <span class=\"greek\">εἰ</span> 2; cf. Hipérides 3, 1; Fílon de Bizâncio, Mech. 77, 41; Políbio 3, 33, 17; PHib 159 [século III a.C.], <span class=\"greek\">θαυμάζω</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">πιστεύεις</span>; Fílon, Migr. Abr. 26; Josefo, C. Ap. 1, 68; Ant. 1, 57 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:13</a>; Dg 10:4; MPol 7:2; 16:1; AcPl Ox 6, 15 (<span class=\"greek\">πῶς</span> em Aa I, 241, 15); AcPlCor 2:2.</p><p class=\"entry-text\">ⓑ Transitivo, <strong>admirar, respeitar, maravilhar-se com</strong>, a respeito de pessoas, com acusativo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">τὶ</span>, «alguma coisa» (Diodoro Sículo 3, 56, 5; Alcífron 4, 6, 3; Herm. Wr. 4, 5; Dn 8:27, Teodocião; Fílon, Abr. 103 e outros; Josefo, Vi. 222; Ar. 1, 1; Justino, A I, 47, 1 e outros; Melitão, P. 22, 148; Atanásio 1, 2 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:31</a> (aqui o imperfeito <span class=\"greek\">θ</span>. talvez signifique «desejar conhecer [alguma coisa]», como em Quíon, Ep. 9, <span class=\"greek\">θ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">συντυχίαν</span>, «desejar saber o que aconteceu»); 1Cl 1:2; 2Cl 13:4, cf. versículo 3; MPol 2:2; 3:2; 7:2. A expressão <span class=\"greek\">θαυμάζειν</span> <span class=\"greek\">πρόσωπα</span>, «mostrar parcialidade», Jd 16 (ver P. Katz, Kratylus 5, 1960, 161), semelhante a <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">λαμβάνειν</span> (cf. D 4:3; B 19:4), ocorre na LXX (Lv 19:15; Dt 10:17; Jó 22:8 e outros; PsSol 2:18) e provavelmente conserva o mesmo sentido, «favorecer pessoas, mostrar parcialidade» (cf. TestMos 5:5).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τινά</span>, «alguém» (Diodoro Sículo 1, 93, 2; Diógenes Laércio 9, 4; Himério, Or. [Ecl.] 3, 20; Josefo, C. Ap. 2, 125; Melitão, P. 92, 691), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:9</a>; Dg 10:7s. Na passiva, <strong>ser admirado</strong> (Heródoto 3, 82; SIG 1073, 41; PGiss 47, 5, <span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδόντων</span> <span class=\"greek\">θαυμασθῆναι</span>; LXX; Taciano 32, 2, <span class=\"greek\">Νέστορα</span> … <span class=\"greek\">θαυμάζεσθαι</span>; Atanásio, R. 51, 31, <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοφίᾳ</span> <span class=\"greek\">θαυμαζομένων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:10</a> (ou segundo ②?).</p><p class=\"entry-text\">② <strong>Admirar-se, assombrar-se</strong>, como depoente com primeiro aoristo e primeiro futuro passivos (Kühner–Blass II 439s.; uma ocorrência assim na LXX, Est 4:17p [Thackeray 240, 1]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:8</a>. Em construção condensada, <span class=\"greek\">ἐθαυμάσθη</span> <span class=\"greek\">ὅλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θηρίου</span>, «a terra inteira, maravilhada, seguiu a besta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:3</a> (a admiração torna-se adoração; cf. Élio Aristides 13, p. 290 D.; 39, p. 747, acerca de Dioniso e Héracles, <span class=\"greek\">οἳ</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐθαυμάσθησαν</span>; Eclo 7:29; Josefo, Ant. 3, 65. A voz ativa também ocorre com essa acepção: Cebes 2, 3, <span class=\"greek\">θ</span>. <span class=\"greek\">τινά</span>, «admirar» ou «venerar» alguém; Epicteto 1, 17, 19, <span class=\"greek\">θ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>). — DELG, s.v. <span class=\"greek\">θαῦμα</span>; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-thaumasios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάσιος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Mais tarde, embora raramente, com duas terminações (ver o verbete precedente e os dois seguintes; desde os Hinos homéricos e Hesíodo; inscrições, papiros, LXX; TestAbr A; TestSim 6:7; Fílon, Josefo, Justino; Taciano 18, 2). <strong>Que provoca admiração ou merece maravilhamento: maravilhoso, notável, admirável</strong>.</p><p class=\"entry-text\">ⓐ De coisas (EpArist 89; Josefo, Vi. 208), <span class=\"greek\">διήγησιν</span> … <span class=\"greek\">θαυμασίαν</span>, «narrativa maravilhosa», Pápias 2:9. Substantivado, <span class=\"greek\">τὰ</span> <span class=\"greek\">θαυμάσια</span>, «coisas maravilhosas, prodígios» (Heródoto 2, 35; Êx 3:20 e frequentemente; TestAbr A 6, p. 83, 26 [Stone, p. 14]; TestSim 6:7; Fílon; Justino), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:15</a>; Hv 4, 1, 3. AcPl Ha 8, 33 = BMM verso 6s., Jesus <span class=\"greek\">ἐποίει</span> <span class=\"greek\">μεγ</span>̣<span class=\"greek\">άλα</span> <span class=\"greek\">καί</span> <span class=\"greek\">θαυμάσια</span>, «fazia coisas grandes e maravilhosas»; também <span class=\"greek\">τὰ</span> … <span class=\"greek\">ἐκῖ</span> <span class=\"greek\">θαυμάσια</span>, «as maravilhas ali», AcPl Ha 2, 23s.</p><p class=\"entry-text\">ⓑ De pessoas (TestSol 1, 13 D; TestAbr A 11, p. 89, 9 e 12 [Stone, p. 26]; SIG 798, 11 [37 d.C.], <span class=\"greek\">θαυμασιώτερος</span>; OGI 504, 12, <span class=\"greek\">θαυμασιώτατος</span>; superlativo também POxy 940 verso; PGiss 57 verso; Fílon, Abr. 38; Josefo, C. Ap. 1, 51; Taciano 18, 2), <span class=\"greek\">ὁ</span> <span class=\"greek\">θαυμασιώτατος</span> <span class=\"greek\">Π</span>., «o mui admirável P.», MPol 5:1; 16:2. — DELG, s.v. <span class=\"greek\">θαῦμα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-thaumastos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte; Hinos homéricos e autores posteriores.) <strong>Que provoca admiração ou merece maravilhamento: maravilhoso, extraordinário, notável</strong> (Diodoro Sículo 1, 36, 7, <span class=\"greek\">θ</span>. intensificado em <span class=\"greek\">παντελῶς</span> <span class=\"greek\">ἄπιστον</span>). Na nossa literatura, não se refere a personalidades humanas, mas a Deus (Dn 9:4, Teodocião; Sl 92:4b), 1Cl 60:1, e a coisas frequentemente ligadas a Deus: o nome (Sl 8:2, 10), Hs 9, 18, 5; D 14:3; a luz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:9</a>, cf. 1Cl 36:2; a glória, Hm 12, 4, 2; um modo de agir (o feminino em lugar do neutro por tradução literal do hebraico; B-D-F §138, 2; Rob. 254), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:11</a> (ambos Sl 117:23); o dia do julgamento, B 6:4; as obras de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:3</a> (cf. Tb 12:22 BA; Eclo 11:4; Élio Aristides 48, 30 K. = 24, p. 473 D.). Com <span class=\"greek\">μέγας</span>, «grande» (como em algumas das passagens anteriores; cf. SIG 1073, 26, <span class=\"greek\">μέγα</span> <span class=\"greek\">τι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμαστόν</span>; LXX; Fílon, Mos. 2, 10; Justino, D. 10, 2; Taciano 25, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:1</a>; 1Cl 26:1; 50:1; 53:3; 2Cl 2:6; 5:5; Hv 1, 3, 3, conjectura de Joly. Com <span class=\"greek\">μέγας</span> e <span class=\"greek\">ἰσχυρός</span>, «forte», Hm 12, 4, 2; com <span class=\"greek\">μακάριος</span>, «bem-aventurado», 1Cl 35:1; com <span class=\"greek\">παράδοξος</span>, «surpreendente» (Menandro, Fgm. 466 Kö.; Justino, D. 133, 1), Dg 5:4. <span class=\"greek\">τί</span> <span class=\"greek\">θαυμαστὸν</span> <span class=\"greek\">εἰ</span>;, «que há de admirável se?» (Epicteto 1, 25, 33; 2, 9, 9; 4Mc 2:1; Fílon, Aet. M. 137; com acusativo e infinitivo, Atanásio 30, 1), 1Cl 43:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θαυμαστόν</span> <span class=\"greek\">ἐστιν</span>, «a coisa extraordinária é esta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:30</a>. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:14</a>, variante de leitura. — DELG, s.v. <span class=\"greek\">θαῦμα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-thaumastos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver verbete precedente; Platão e outros; SIG 796a, 8; Herm. Wr. 506, 17 Sc.; LXX.) <strong>Maravilhosamente</strong>. <span class=\"greek\">ἤκουσα</span> <span class=\"greek\">μεγάλως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θ</span>., «ouvi coisas grandes e maravilhosas», Hv 1, 3, 3 (o significado é inconfundível, mas o texto provavelmente está danificado; ver M. Dibelius, <em>Handbuch</em>, ad loc.; opinião diversa de Joly, ver <span class=\"greek\">θαυμαστός</span>). <span class=\"greek\">μεγάλως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμαστῶς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐστί</span>, «todas as coisas são grandes e maravilhosas», Hs 5, 5, 4. <span class=\"greek\">μεγάλως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἔχει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρᾶγμα</span> <span class=\"greek\">τοῦτο</span>, «essa questão é grande e maravilhosa», Hv 3, 4, 1 (<span class=\"greek\">θ</span>. <span class=\"greek\">ἔχειν</span>, como em EpArist 58). — DELG, s.v. <span class=\"greek\">θαῦμα</span>.</p></section></article>\n<article id=\"entry-thea-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros; TestSol 15:3; Ar.) <strong>Ser transcendente concebido como feminino, normalmente entendido como protetor ou fonte de benefícios especiais aos devotos e, portanto, digno de elevada admiração e respeito: deusa</strong>. De Ártemis, <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">θεά</span>, «a grande deusa» (cf. IBM III, 481, 324s., <span class=\"greek\">τῇ</span> <span class=\"greek\">μεγίστῃ</span> <span class=\"greek\">θεᾷ</span> <span class=\"greek\">Ἐφεσίᾳ</span> <span class=\"greek\">Ἀρτέμιδι</span>; <span class=\"greek\">θεὰ</span> <span class=\"greek\">μεγάλη</span>, «grande deusa», de Ísis: OGI 92, 3 [cerca de 200 a.C.]; <span class=\"greek\">θεὰ</span> <span class=\"greek\">μήτηρ</span>, «deusa-mãe», de Reia, Orígenes, C. Cels. 4, 48, 11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:27</a>, 37, variante de leitura. <span class=\"greek\">ὡς</span> <span class=\"greek\">θεάν</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἡγησάμην</span>, «considerei-te uma deusa», Hv 1, 1, 7 (<span class=\"greek\">ὡς</span> <span class=\"greek\">θεὰ</span> <span class=\"greek\">λεγομένη</span>, «chamada deusa», TestSol 15:3); Hermas ressalta ter apenas a mais elevada consideração por Roda, cuja beleza havia admirado. — DELG, s.v. <span class=\"greek\">θεός</span>; M-M; TW.</p></section></article>\n<article id=\"entry-theama-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέαμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte; Semônides, Fgm. 7, 67; Ésquilo; Estrabão 14, 2, 5, a respeito das sete «maravilhas» do mundo; CPJ 519, 60 [séculos II/III d.C.]; Êx 3:3, Símaco; Fílon; Josefo; Melitão, P. 19, 127; 29, 197.) <strong>Algo notável exposto à vista: visão, espetáculo</strong>, GJs 19:2s. — DELG, s.v. <span class=\"greek\">θέα</span>.</p></section></article>\n<article id=\"entry-theaomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεάομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">θεάσομαι</span>, TestSol D 4, 9; primeiro aoristo <span class=\"greek\">ἐθεασάμην</span>; perfeito <span class=\"greek\">τεθέαμαι</span>; primeiro aoristo passivo com sentido passivo <span class=\"greek\">ἐθεάθην</span> (ático [Kühner–Blass II 441] e posteriores).</p><p class=\"entry-text\">① <strong>Olhar intencionalmente para alguma coisa, apreendê-la com os olhos, com a implicação de impressão especial: ver, olhar, contemplar</strong>.</p><p class=\"entry-text\">ⓐ Em sentido literal (POxy 963; Sb 1800; Josefo, Ant. 3, 132; 6, 340), alternando com <span class=\"greek\">ὁρᾶν</span>, Hv 3, 8, 1. Com acusativo de objeto (Homero, Ilíada 7, 444; Hesíodo, Trabalhos 482; PSI 41, 19; Tb 2:2 BA; 2Mc 2:4; En 6:2; 21:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:10</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:27</a>; 22:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1:1</a> (<span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">ἡμῶν</span>, «com nossos olhos»; cf. Fílon, Mos. 1, 278, <span class=\"greek\">θ</span>. <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ὀφθαλμοῖς</span>); 4:12 (P. van der Horst, ZNW 63, 1972, 280–82 [jogo de palavras]). O objeto acusativo frequentemente vem com particípio que indica o observado na pessoa ou coisa (En 9:1; 23:2; Fílon, Vi. Cont. 89; Josefo, Vi. 28, 281; B-D-F §416, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:14</a>. <span class=\"greek\">ἐθεάσατο</span> <span class=\"greek\">τελώνην</span> <span class=\"greek\">καθήμενον</span>, «viu um cobrador de impostos sentado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:27</a>; 6:4, códice D (<em>Unknown Sayings</em>, 49–54). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:11</a>. Com <span class=\"greek\">ὅτι</span> subsequente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:5</a>. Acusativo e <span class=\"greek\">ὅτι</span>: <span class=\"greek\">θεάσασθε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χώρας</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">λευκαί</span> <span class=\"greek\">εἰσιν</span>, «vede que os campos estão brancos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35</a>. Acusativo e <span class=\"greek\">ὡς</span>: <span class=\"greek\">ἐθεάσαντο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐτέθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">αὐτοῦ</span>, «viram o túmulo e como seu corpo havia sido posto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:55</a>. Acusativo e <span class=\"greek\">εἰ</span>, «verificar se», GJs 1:3 (códices, não no papiro). Acusativo e <span class=\"greek\">ὅπως</span>, em construção entrelaçada: <span class=\"greek\">ὅταν</span> <span class=\"greek\">θεάσωνται</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρνησαμένους</span> <span class=\"greek\">ὅπως</span> <span class=\"greek\">κολάζονται</span>, «quando veem como são castigados aqueles que negaram», 2Cl 17:7. Seguido de oração relativa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:45</a> (<span class=\"greek\">ὁράω</span> nos papiros P45 e P66). <span class=\"greek\">θεασάμενος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">ἐποίησεν</span>, «ele [José] tinha visto todas as boas coisas que ele [Jesus] fizera», GPt 6:23.</p><p class=\"entry-text\">ⓑ A passiva significa: <span class=\"greek\">α</span>. <strong>ser visto</strong>, <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, «por alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:11</a>; ou <span class=\"greek\">β</span>. <strong>ser notado, atrair atenção</strong>, <span class=\"greek\">τινί</span>, «de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:1</a>; 23:5 (ver B-D-F §191, 1; Rob. 542, também 534).</p><p class=\"entry-text\">② <strong>Ver com o propósito de visitar: ir ver, visitar</strong> (Apiano, Samn. 7, §1, <span class=\"greek\">θ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἑλλάδα</span>, «visitar a Grécia»), <span class=\"greek\">τινά</span>, «alguém» (2Cr 22:6; Josefo, Ant. 16, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:24</a> (Paulo elogia a congregação como atração digna de visita em sua viagem planejada). Pertence aqui <span class=\"greek\">εἰσελθὼν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">θεάσασθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνακειμένους</span>, «o rei entrou para observar os convidados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:11</a> (implica examiná-los).</p><p class=\"entry-text\">③ <strong>Perceber algo além daquilo que os olhos simplesmente veem: ver, contemplar, perceber</strong>.</p><p class=\"entry-text\">ⓐ Com olhos físicos, <strong>receber impressão de algo transcendente, ver, contemplar</strong> (cf. PParis 51, 38 [160 a.C.], visão no templo de Serápis em Mênfis, <span class=\"greek\">τὸ</span> <span class=\"greek\">ὅραμα</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τεθήαμαι</span>; SIG 730, 20; 2Mc 3:36; Tb 13:7; Jt 15:8; En 106:13): <span class=\"greek\">τεθέαμαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καταβαῖνον</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">περιστεράν</span>, «vi o Espírito descer como pomba», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:32</a> (vê a pomba e percebe que é o Espírito); <span class=\"greek\">ἐθεασάμεθα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δόξαν</span> <span class=\"greek\">αὐτοῦ</span>, «contemplamos sua glória», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:14</a> (viram a pessoa e a obra de Cristo e nelas perceberam a glória divina; cf. Tb 13:16 BA, <span class=\"greek\">θεασάμενοι</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δόξαν</span> <span class=\"greek\">σου</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:14</a>.</p><p class=\"entry-text\">ⓑ <strong>Percepção inteiramente não sensorial: perceber</strong> (Xenofonte, Hiero 2, 5; com <span class=\"greek\">ὅτι</span>, Platão, Prot. 352a; Demóstenes 4, 3; <span class=\"greek\">θεὸν</span> <span class=\"greek\">θ</span>., «ver Deus», Teófilo de Antioquia 1, 2 [p. 60, 12]), Dg 10:7. <span class=\"greek\">θεασάμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πολλὴν</span> <span class=\"greek\">πλάνην</span>, «percebendo grande erro em nós», 2Cl 1:7. — DELG, s.v. <span class=\"greek\">θέα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-theatrizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Inscrição de Gérasa: JRS 18, 1928, 144ss., n.º 14, 18 [cerca de 102–114 d.C.], na qual a palavra aparece certamente, embora seu significado seja incerto; ver H. Cadbury, ZNW 29, 1930, 60–63; Acmes 21, 5, <span class=\"greek\">ἀτίμως</span> <span class=\"greek\">θεατρισθήσεται</span>; 51, 11; Suda II 688, 26; crônica bizantina em Psaltes, p. 328; <span class=\"greek\">ἐκθεατρίζω</span> em Políbio 3, 91, 10 e Diodoro Sículo 34+35 Fgm. 2, 46.) <strong>Envergonhar, expor publicamente</strong>: <span class=\"greek\">ὀνειδισμοῖς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θλίψεσιν</span> <span class=\"greek\">θεατριζόμενοι</span>, «expostos publicamente a insultos e tribulações», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a> (Posidônio: 87 Fgm. 108 [apêndice] Jac., <span class=\"greek\">ἐξεθεάτριζον</span> <span class=\"greek\">ὀνειδίζοντες</span>). — DELG, s.v. <span class=\"greek\">θέα</span>; TW.</p></section></article>\n<article id=\"entry-theatron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέατρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes precedentes; Tucídides e outros; inscrições, papiros, Fílon, Josefo; Justino, D. 122, 4; Taciano 8, 1; empréstimo ao vocabulário rabínico.) Originalmente <strong>lugar para ver</strong>, sobretudo produções dramáticas (Heródoto 6, 67, 3).</p><p class=\"entry-text\">① <strong>Local de assembleias públicas: teatro</strong> (Diodoro Sículo 16, 84, 3, <span class=\"greek\">δῆμος</span> <span class=\"greek\">ἅπας</span> <span class=\"greek\">συνέδραμεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέατρον</span>, «o povo todo correu para o teatro»; Cáriton 8, 7, 1; Polieno 8, 21; IBM III, 481, 395, <span class=\"greek\">φερέτωσαν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέατρον</span> [Éfeso]; inscrição do teatro de Éfeso [103/104 d.C.] em Deissmann, LO 90s. [LAE 114] = OGI 480, 9; ver também índice de SIG; Josefo, Bell. 7, 47, 107; Ant. 17, 161), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:29</a>, 31; AcPl Ha 1, 24.</p><p class=\"entry-text\">② <strong>Aquilo que é visto num teatro: peça teatral, espetáculo</strong> (Pseudo-Platão, Axioch. 371c; Aquiles Tácio 1, 16, 3), figuradamente <span class=\"greek\">θ</span>. <span class=\"greek\">ἐγενήθημεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, «tornamo-nos espetáculo para o mundo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:9</a> (Sinésio, Prov. 1, 10, p. 100c, <span class=\"greek\">θεαταὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">καλῶν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἀγώνων</span>; Salústio, <em>Jugurtha</em> 14, 23; Plínio, o Jovem, <em>Panegyricus</em> 33, 3; H. Conzelmann, <em>1 Corinthians</em> [Hermeneia], ad loc.). — DELG, s.v. <span class=\"greek\">θέα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-thegri-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεγρί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável. <strong>Tegrí</strong>, anjo encarregado dos animais, Hv 4, 2, 4. Sobre ele e seu nome, ver M. Dibelius, <em>Handbuch</em>, excursus ao trecho; ver <span class=\"greek\">Σεγρί</span>.</p></section></article>\n<article id=\"entry-theion-sulfur-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Homero [formas <span class=\"greek\">θέειον</span> e <span class=\"greek\">θήιον</span>]; papiros, LXX; Josefo, Bell. 7, 189; SibOr 3, 691; Justino, A I, 53, 8.) <strong>Enxofre</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:29</a> (Gn 19:24); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:17s</a>. (com <span class=\"greek\">καπνός</span> e <span class=\"greek\">πῦρ</span>, como em Fílon, Mos. 2, 56); 14:10; 19:20; 20:10; 21:8; 1Cl 11:1. — DELG, s.v. <span class=\"greek\">θεός</span>.</p></section></article>\n<article id=\"entry-theios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεῖος, θεία, θεῖον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Homero; advérbio <span class=\"greek\">θείως</span>, Justino, A I, 20, 3. — R. Muquier, <em>Le sens du mot <span class=\"greek\">θεῖος</span> chez Platon</em>, 1930; J. van Camp e P. Canart, <em>Le sens du mot theios chez Platon</em>, 1956.)</p><p class=\"entry-text\">① <strong>Relativo à natureza ou condição da divindade: divino</strong>.</p><p class=\"entry-text\">ⓐ Adjetivo <strong>divino</strong>. <span class=\"greek\">δύναμις</span>, «poder» (Platão, Leg. 3, 691e, <span class=\"greek\">φύσις</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἀνθρωπίνη</span> <span class=\"greek\">μεμιγμένη</span> <span class=\"greek\">θείᾳ</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">δυνάμει</span>; Díon Crisóstomo 14 [31], 95; decreto de Estratoniceia, CIG II 2715ab [Deissmann, B. 277ss. = BS 360ss.]; EpArist 157 e outros; Fílon, Det. Pot. Ins. 83 e outros; SibOr 5, 249; Justino, A I, 32, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:3</a>. <span class=\"greek\">φύσις</span>, «natureza» (Diodoro Sículo 5, 31, 4; Díon Crisóstomo 11 [12], 29; Élio Aristides 37, 9 K. = 2, p. 16 D.; Manetão: 609 Fgm. 10, p. 92, 16 Jac. [Josefo, C. Ap. 1, 232]; SIG 1125, 8; Fílon, Decal. 104, <span class=\"greek\">τῶν</span> <span class=\"greek\">θείας</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">μετεσχηκότων</span>; Josefo, Ant. 8, 107), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:4</a>. <span class=\"greek\">κρίσις</span>, «juízo» (Simplício sobre Epicteto, p. 20, 30; Fílon, Spec. Leg. 3, 12, 1), 2Cl 20:4. <span class=\"greek\">γνῶσις</span>, «conhecimento» (cf. 4Mc 1:16), 1Cl 40:1. <span class=\"greek\">πνεῦμα</span>, «espírito» (Menandro, Fgm. 417, 3 Kö. [= 482, 3 Kock]; PGM 4, 966; Aristóbulo, p. 218, 5 Denis [Eusébio, PE 8, 10, 4 = Holladay, p. 136, linha 28]; ApcSed 14:6; Fílon; Josefo, Ant. 6, 222; 8, 408; 10, 239; Justino, A I, 32, 2 e outros; Taciano 13, 2; cf. 4:2, <span class=\"greek\">θειοτέρου</span>), Hm 11:2, 5, 7ss., 12, 21 (TestSol 1:10 L). <span class=\"greek\">ἔργα</span>, «obras» das Virtudes, Hv 3, 8, 7.</p><p class=\"entry-text\">ⓑ Substantivado <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>, <strong>ser divino, divindade</strong>, frequentemente simplesmente «o numinoso» (Heródoto 3, 108; Tucídides 5, 70; Xenofonte, Cyr. 4, 2, 15; Hell. 7, 5, 13; Mem. 1, 4, 18; Platão, Phdr. 242c; Políbio 31, 15, 7; Diodoro Sículo 1, 6, 1; 13, 3, 2; 16, 60, 2; Epicteto 2, 20, 22; Luciano, De Sacrif. 1; Pro Imag. 13, 17, 28; Herm. Wr. 11, 21b, códices; inscrições [índice SIG p. 377s.]; UPZ 24, 11; 36, 13, 22; 39, 5; Mitt-Wilck. I/2, 70, 14; 116, 2, <span class=\"greek\">σέβου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>; PGM 3, 192; Fílon, Op. M. 170; Agr. 80; Leg. ad Gai. 3; Josefo, Ant. 1, 85, 194; 2, 275; 5, 133; 11, 127; 12, 281, 302; 13, 242, 300; 14, 183; 17, 41; Bell. 3, 352; 4, 190; Justino, D. 3, 7 e outros; Taciano 16, 2; Atanásio 1, 2 e outros). A LXX, En, EpArist, SibOr e outros pseudepígrafos não empregam <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:27</a>, códice D; 17:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:9</a>, variante de leitura. — New Docs 3, 68 (inscrição).</p><p class=\"entry-text\">② <strong>De pessoas que se encontram em relação estreita com uma divindade ou refletem características dela, especialmente a disposição de beneficiar aqueles a quem servem: divino</strong> (Diógenes Laércio 7, 119: a Estoa afirma dos <span class=\"greek\">σοφοί</span>, <span class=\"greek\">θείους</span> <span class=\"greek\">εἶναι</span>· <span class=\"greek\">ἔχειν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">οἱονεὶ</span> <span class=\"greek\">θεόν</span>; cf. Platão, Rep. 366c). Sobre <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">θεῖοι</span>, «homens divinos», cf. Reitzenstein, <em>Mysterienrel.</em>³ 25s., 237ss., 298; H. Windisch, <em>Pls u. Christus</em>, 1934, 1–114; B. Gildersleeve, <em>Essays and Studies</em>, 1896, 251–96 [Apolônio de Tiana]; L. Bieler, <em><span class=\"greek\">Θεῖος</span> <span class=\"greek\">Ἀνήρ</span></em> I, 1935; II, 1936; C. Holladay, <em>Theios Aner in Hellenistic Judaism</em>, 1972; J. Kingsbury, Int 35, 1981, 243–57 [cristologia de Marcos]; E. Koskenniemi, <em>Apollonios von Tyana in der neutestamentlichen Exegese</em>, 1994. No superlativo (Enomau em Eusébio, PE 5, 28, 2: Licurgo como <span class=\"greek\">ὁ</span> <span class=\"greek\">θειότατος</span> <span class=\"greek\">ἀνθρώπων</span>; Jâmblico, Vi. Pyth. 29, 161, <span class=\"greek\">ὁ</span> <span class=\"greek\">θειότατος</span> <span class=\"greek\">Πυθαγόρας</span>; de imperadores, inscrições [índice SIG p. 378a] e papiros [PLond III, 1012, 4, p. 266]), <span class=\"greek\">οἱ</span> <span class=\"greek\">θειότατοι</span> <span class=\"greek\">προφῆται</span>, «os profetas, homens tão próximos de Deus», IMg 8:2 (cf. TestSol 1:4 C, <span class=\"greek\">ὦ</span> <span class=\"greek\">θεῖε</span> <span class=\"greek\">βασιλεῦ</span>; Fílon, Mos. 2, 188; Josefo, Ant. 10, 35, <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">θεῖος</span>; C. Ap. 1, 279 [Moisés]). Dos anjos, Pápias 4.</p><p class=\"entry-text\">③ <strong>Aquilo que excede os limites da possibilidade humana ou terrena: sobrenatural</strong> (Luciano, Alex. 12, <span class=\"greek\">θεῖόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φοβερόν</span>), acerca de um monstro: <span class=\"greek\">ὑπενόησα</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">τι</span> <span class=\"greek\">θεῖον</span>, «suspeitei que fosse algo sobrenatural», Hv 4, 1, 6. — RAC XIII 155–366; DELG, s.v. <span class=\"greek\">θεός</span>; M-M; TW; Sv.</p></section></article>\n"};
